<script setup lang="ts">
import { computed, ref } from 'vue'
import { budgetSpent, categoryPath, localDay, rangeForPreset, transactionShareAmount, type LedgerSnapshot, type Transaction } from './ledger'
import { money } from './ledgerViewModels'
import UiIcon from './UiIcon.vue'
import CategoryIcon from './CategoryIcon.vue'
const props = defineProps<{ snapshot: LedgerSnapshot; period: 'week'|'month'|'year' }>()
const emit = defineEmits<{ 'update:period': [value:'week'|'month'|'year']; calendar: []; pin: []; range: [id:string]; 'remove-range': [id:string]; budgets: []; 'create-budget': []; entry: []; import: []; transactions: []; edit: [transaction:Transaction] }>()
const chartMode = ref<'bar'|'pie'>('bar')
const range = computed(() => rangeForPreset(props.period))
const rows = computed(() => props.snapshot.transactions.filter(tx => tx.includeInStatistics && new Date(tx.happenedAt) >= range.value.start && new Date(tx.happenedAt) < range.value.end))
const sum = (kind: 'expense'|'income') => rows.value.filter(tx => tx.kind === kind).reduce((total, tx) => total + transactionShareAmount(tx), 0)
const totals = computed(() => ({ expense: sum('expense'), income: sum('income'), discount: rows.value.filter(tx=>tx.kind==='expense').reduce((n,tx)=>n+(tx.discountAmount||0),0), premium: rows.value.filter(tx=>tx.kind==='expense').reduce((n,tx)=>n+(tx.premiumAmount||0),0) }))
const periodLabel = computed(() => props.period === 'week' ? '本周' : props.period === 'month' ? '本月' : '本年')
const budgets = computed(() => props.snapshot.budgets.map(budget => {
  const start = budget.periodType === 'monthly' ? new Date(budget.year,(budget.month||1)-1,1) : new Date(`${budget.startDate}T00:00:00`)
  const end = budget.periodType === 'monthly' ? new Date(budget.year,budget.month||1,1) : new Date(`${budget.endDate}T00:00:00`)
  if(budget.periodType !== 'monthly') end.setDate(end.getDate()+1)
  return { ...budget, spent:budgetSpent(props.snapshot,budget,start,end), active: new Date() >= start && new Date() < end }
}))
const activeBudgets = computed(() => budgets.value.filter(budget => budget.active))
const budgetLeft = computed(() => activeBudgets.value.reduce((total,budget)=>total+budget.limitAmount-budget.spent,0))
const categories = computed(() => {
  const groups = new Map<string,{id:string;name:string;icon:string;color:string;amount:number}>()
  for(const tx of rows.value.filter(tx=>tx.kind==='expense')){
    const category = categoryPath(props.snapshot.categories,tx.categoryId)[0]
    const id=category?.id||'unassigned'
    const item=groups.get(id)||{id,name:category?.name||'未分类',icon:category?.icon||'grid',color:category?.color||'#8396af',amount:0}
    item.amount+=transactionShareAmount(tx);groups.set(id,item)
  }
  const result=[...groups.values()].sort((a,b)=>b.amount-a.amount)
  if(result.length>6){const rest=result.splice(5);result.push({id:'other',name:'其他分类',icon:'grid',color:'#94a3b8',amount:rest.reduce((n,item)=>n+item.amount,0)})}
  let cursor=0
  return result.map(item=>{const percent=totals.value.expense?item.amount/totals.value.expense*100:0;const start=cursor;cursor+=percent;return{...item,percent,start,end:cursor}})
})
const pie = computed(() => `conic-gradient(${categories.value.map(item=>`${item.color} ${item.start}% ${item.end}%`).join(',')})`)
const trend = computed(() => {
  const count=props.period==='year'?12:Math.round((range.value.end.getTime()-range.value.start.getTime())/86400000)
  const points=Array.from({length:count},(_,i)=>({label:props.period==='year'?`${i+1}月`:String(props.period==='week'?new Date(range.value.start.getFullYear(),range.value.start.getMonth(),range.value.start.getDate()+i).getDate():i+1),income:0,expense:0}))
  for(const tx of rows.value){const date=new Date(tx.happenedAt);const index=props.period==='year'?date.getMonth():Math.round((new Date(date.getFullYear(),date.getMonth(),date.getDate()).getTime()-range.value.start.getTime())/86400000);if(points[index])points[index][tx.kind]+=transactionShareAmount(tx)}
  const max=Math.max(1,...points.flatMap(point=>[point.income,point.expense]))
  return points.map((point,index)=>({...point,incomeHeight:point.income/max*100,expenseHeight:point.expense/max*100,showLabel:points.length<=12||index===0||index===points.length-1||(index+1)%7===0}))
})
const recent = computed(() => [...rows.value].sort((a,b)=>b.happenedAt.localeCompare(a.happenedAt)).slice(0,5))
const categoryFor = (id:string|null) => props.snapshot.categories.find(category=>category.id===id)
const expenseDaily = computed(() => { const now=new Date();const days=Math.max(1,Math.round((Math.min(now.getTime(),range.value.end.getTime())-range.value.start.getTime())/86400000)+1);return totals.value.expense/days })
</script>
<template>
  <section class="home-dashboard">
    <div class="home-intro"><div><span class="home-eyebrow">YOUR MONEY, AT A GLANCE</span><h2>每一笔，都心中有数。</h2><p>{{ new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}) }} · 记录生活，也为下一程留好预算</p></div><button type="button" class="feature-button" @click="emit('import')"><UiIcon name="scan" :size="17"/>截图记账</button></div>
    <div class="home-period-bar"><div class="home-segments" aria-label="统计周期"><button v-for="key in ['week','month','year'] as const" :key="key" type="button" :aria-pressed="period===key" :class="{active:period===key}" @click="emit('update:period',key)">{{ key==='week'?'本周':key==='month'?'本月':'本年' }}</button></div><span class="home-period-dates">{{ localDay(range.start).replaceAll('-','.') }} — {{ localDay(new Date(range.end.getTime()-1)).replaceAll('-','.') }}</span><div class="home-period-actions"><button type="button" class="feature-icon-button" title="置顶统计区间" aria-label="置顶统计区间" @click="emit('pin')"><UiIcon name="pin" :size="17"/></button><button type="button" class="feature-button" @click="emit('calendar')"><UiIcon name="calendar" :size="17"/>收支日历</button></div></div>
    <div v-if="snapshot.pinnedRanges.length" class="home-pinned"><div v-for="item in snapshot.pinnedRanges" :key="item.id"><button type="button" @click="emit('range',item.id)"><UiIcon name="pin" :size="12"/>{{ item.name }}</button><button type="button" :aria-label="`取消置顶${item.name}`" @click="emit('remove-range',item.id)"><UiIcon name="close" :size="13"/></button></div></div>
    <div class="home-summary"><article class="home-expense-card"><header><span>{{ periodLabel }}总支出</span><UiIcon name="expense" :size="22"/></header><strong>{{ money(totals.expense) }}</strong><footer><span>日均支出 <b>{{ money(expenseDaily) }}</b></span><span>{{ rows.length }} 笔收支记录</span></footer></article><article class="home-money-card"><header><span>{{ periodLabel }}总收入</span><i class="home-income-icon"><UiIcon name="income" :size="18"/></i></header><strong class="home-income">{{ money(totals.income) }}</strong><footer>收入的每一份，都值得记录</footer></article><article class="home-money-card"><header><span>{{ periodLabel }}结余</span><i><UiIcon name="wallet" :size="18"/></i></header><strong>{{ money(totals.income-totals.expense) }}</strong><footer>总收入 − 总支出</footer></article></div>
    <div class="home-mini-stats"><div><i><UiIcon name="budget" :size="19"/></i><span><small>当前预算剩余</small><strong :class="{'home-warning':budgetLeft<0}">{{ money(budgetLeft) }}</strong></span><b>{{ activeBudgets.length }} 个预算</b></div><div><i class="home-saving-icon"><UiIcon name="tag" :size="19"/></i><span><small>{{ periodLabel }}优惠</small><strong>{{ money(totals.discount) }}</strong></span></div><div><i class="home-premium-icon"><UiIcon name="premium" :size="19"/></i><span><small>{{ periodLabel }}溢价</small><strong>{{ money(totals.premium) }}</strong></span></div></div>
    <div class="home-charts"><article class="home-panel home-category-chart"><header class="home-panel-heading"><div><h3>钱花在哪里</h3><p>按一级分类汇总支出</p></div><div class="home-segments compact"><button type="button" :class="{active:chartMode==='bar'}" :aria-pressed="chartMode==='bar'" @click="chartMode='bar'">排行</button><button type="button" :class="{active:chartMode==='pie'}" :aria-pressed="chartMode==='pie'" @click="chartMode='pie'">环图</button></div></header><div v-if="categories.length" class="home-distribution" :class="{'with-donut':chartMode==='pie'}"><div v-if="chartMode==='pie'" class="home-donut" :style="{background:pie}" role="img" aria-label="分类支出占比环图"><div><small>总支出</small><b>{{ money(totals.expense) }}</b></div></div><div class="home-category-rows"><div v-for="item in categories" :key="item.id" class="home-category-row"><span class="home-category-name"><i :style="{background:item.color}"></i>{{ item.name }}</span><strong>{{ money(item.amount) }}<small>{{ item.percent.toFixed(1) }}%</small></strong><div v-if="chartMode==='bar'" class="home-track"><i :style="{width:`${item.percent}%`,background:item.color}"></i></div></div></div></div><div v-else class="home-empty"><span><UiIcon name="chart" :size="29"/></span><b>还没有支出记录</b><p>记下第一笔，看看钱都花在哪里</p><button type="button" class="feature-text-button" @click="emit('entry')">记一笔 <UiIcon name="plus" :size="14"/></button></div></article>
    <article class="home-panel home-trend-panel"><header class="home-panel-heading"><div><h3>收支趋势</h3><p>{{ period==='year'?'每月':'每天' }}的收支，一目了然</p></div><div class="home-legend"><span><i></i>支出</span><span><i></i>收入</span></div></header><div v-if="rows.length" class="home-trend"><div class="home-trend-grid"></div><div v-for="point in trend" :key="point.label" class="home-trend-column" :title="`${point.label}${period==='year'?'':'日'}：支出 ${money(point.expense)}，收入 ${money(point.income)}`"><div class="home-trend-bars"><i :style="{height:`${point.expenseHeight}%`,opacity:point.expense?1:0}"></i><i :style="{height:`${point.incomeHeight}%`,opacity:point.income?1:0}"></i></div><small>{{ point.showLabel?point.label:' ' }}</small></div></div><div v-else class="home-empty"><span><UiIcon name="trend" :size="29"/></span><b>从第一笔开始积累</b><p>记录收支后，会在这里呈现变化趋势</p></div><footer v-if="rows.length" class="home-chart-footnote">{{ periodLabel }}收入 {{ money(totals.income) }}<span>支出 {{ money(totals.expense) }}</span></footer></article></div>
    <div class="home-bottom"><article class="home-panel"><header class="home-panel-heading"><div><h3>预算进度</h3><p>让每一份计划都有余地</p></div><button type="button" class="feature-text-button" @click="emit('budgets')">管理预算<UiIcon name="chevron" :size="14"/></button></header><div v-if="activeBudgets.length" class="home-budget-list"><div v-for="budget in activeBudgets.slice(0,4)" :key="budget.id"><div><b>{{ budget.name }}</b><small :class="{'home-warning':budget.spent>budget.limitAmount}">{{ (budget.spent/budget.limitAmount*100).toFixed(0) }}%</small></div><div class="home-track"><i :class="{over:budget.spent>budget.limitAmount}" :style="{width:`${Math.min(100,budget.spent/budget.limitAmount*100)}%`}"></i></div><p>已用 {{ money(budget.spent) }}<span>预算 {{ money(budget.limitAmount) }}</span></p></div></div><div v-else class="home-empty small"><span><UiIcon name="budget" :size="25"/></span><b>给生活一个小计划</b><p>{{ snapshot.budgets.length?'当前没有进行中的预算':'设置预算，更从容地安排每月开销' }}</p><button type="button" class="feature-button" @click="emit('create-budget')">新建预算</button></div></article><article class="home-panel"><header class="home-panel-heading"><div><h3>最近记录</h3><p>{{ periodLabel }}的生活足迹</p></div><button type="button" class="feature-text-button" @click="emit('transactions')">全部流水<UiIcon name="chevron" :size="14"/></button></header><div v-if="recent.length" class="home-recent"><button v-for="tx in recent" :key="tx.id" type="button" @click="emit('edit',tx)"><span class="home-recent-icon"><CategoryIcon :name="categoryFor(tx.categoryId)?.icon" :color="categoryFor(tx.categoryId)?.color" :flow-type="tx.kind" :size="20"/></span><span><b>{{ tx.title }}</b><small>{{ localDay(tx.happenedAt).slice(5).replace('-','月') }}日 · {{ categoryFor(tx.categoryId)?.name||'未分类' }}</small></span><strong :class="{'home-income':tx.kind==='income'}">{{ tx.kind==='expense'?'−':'+' }}{{ money(tx.amount) }}</strong></button></div><div v-else class="home-empty small"><span><UiIcon name="book" :size="25"/></span><b>生活值得被记录</b><p>手动记一笔，或导入一张账单截图</p><button type="button" class="feature-button" @click="emit('entry')">开始记账</button></div></article></div>
  </section>
</template>
